use std::sync::Arc;

/// Load environment variables from the nearest `.env` file into an
/// in-process cache.
///
/// 1. Walks upward from `CARGO_MANIFEST_DIR` (if set) or the current working
///    directory to find the nearest `.env` file.
/// 2. Parses each `KEY=VALUE` line (skipping blanks and `#`-comments).
/// 3. Retains every key that is **not** already present in the process
///    environment (real environment variables always win).
/// 4. Returns that [`HashMap`](std::collections::HashMap) of overlay values.
///
/// Results are cached via [`OnceLock`](std::sync::OnceLock), so the file is
/// read at most once and subsequent calls are free.
///
/// # This does not modify the process environment
///
/// Values are only an *overlay*: they are visible through [`env_var`], and
/// nowhere else. [`std::env::var`] will not see them, and neither will
/// anything that reads the environment directly — including the embedded
/// Python SDK and the spawned `localharness` child process. Anything that
/// must reach a child process has to be passed explicitly (for example via
/// [`AgentConfig`]'s `api_key` / `base_url` fields,
/// which are resolved through [`env_var`]).
///
/// Not calling [`std::env::set_var`] is deliberate: it is `unsafe` in
/// Rust 2024 and unsound once any other thread exists.
///
/// # Example
///
/// ```
/// let new_vars = agy_bridge::load_dotenv();
/// // OnceLock-cached: safe to call multiple times, only loads .env once.
/// assert!(new_vars.len() < usize::MAX);
/// ```
static DOTENV_CACHE: std::sync::OnceLock<std::collections::HashMap<String, String>> =
    std::sync::OnceLock::new();

pub fn load_dotenv() -> &'static std::collections::HashMap<String, String> {
    DOTENV_CACHE.get_or_init(|| {
        let start = std::env::var_os("CARGO_MANIFEST_DIR").map_or_else(
            || {
                std::env::current_dir().unwrap_or_else(|e| {
                    tracing::debug!("load_dotenv: current_dir() failed: {e}, using fallback \".\"");
                    std::path::PathBuf::from(".")
                })
            },
            std::path::PathBuf::from,
        );

        let mut dir = start.as_path();
        loop {
            let candidate = dir.join(".env");
            if candidate.is_file() {
                let mut env_map = std::collections::HashMap::new();
                match std::fs::read_to_string(&candidate) {
                    Ok(contents) => {
                        for line in contents.lines() {
                            if let Some((k, v)) = parse_dotenv_line(line)
                                && std::env::var_os(k).is_none()
                            {
                                env_map.insert(k.to_owned(), v.to_owned());
                            }
                        }
                    }
                    Err(e) => {
                        tracing::warn!(error = %e, "Failed to read .env file at {}", candidate.display());
                    }
                }
                return env_map;
            }
            match dir.parent() {
                Some(parent) => dir = parent,
                None => return std::collections::HashMap::new(),
            }
        }
    })
}

/// Look up an environment variable, checking the process environment first and
/// falling back to the cached `.env` values only if [`load_dotenv`] was called.
#[must_use]
pub fn env_var(key: &str) -> Option<String> {
    match std::env::var(key) {
        Ok(val) => Some(val),
        Err(e) => {
            tracing::trace!(key, error = %e, "env_var: not set in environment, checking cached .env");
            DOTENV_CACHE.get().and_then(|map| map.get(key)).cloned()
        }
    }
}

/// Parse a single line from a `.env` file.
///
/// Returns `Some((key, value))` for valid `KEY=VALUE` lines, stripping
/// surrounding whitespace and quotes (single or double) from the value.
/// Returns `None` for blank lines, comments, or lines without `=`.
///
/// This is factored out of [`load_dotenv`] for testability.
pub(crate) fn parse_dotenv_line(line: &str) -> Option<(&str, &str)> {
    let line = line.trim();
    if line.is_empty() || line.starts_with('#') {
        return None;
    }
    let (k, v) = line.split_once('=')?;
    let k = k.trim();
    if k.is_empty() {
        return None;
    }
    let v = v.trim();
    // Strip surrounding quotes (single or double)
    let v = v
        .strip_prefix('"')
        .and_then(|s| s.strip_suffix('"'))
        .or_else(|| v.strip_prefix('\'').and_then(|s| s.strip_suffix('\'')))
        .unwrap_or(v);
    Some((k, v))
}

#[cfg(feature = "native")]
pub type DefaultRuntime = runtime::NativeRuntime;

#[cfg(all(not(feature = "native"), feature = "python"))]
pub type DefaultRuntime = runtime::PythonRuntime;

#[cfg(not(any(feature = "native", feature = "python")))]
pub type DefaultRuntime = runtime::UnconfiguredRuntime;

#[cfg(feature = "python")]
pub type PythonAgent = agent::AgentHandle<runtime::PythonRuntime>;

#[cfg(feature = "native")]
pub type NativeAgent = agent::AgentHandle<runtime::NativeRuntime>;

/// Convenience alias for an agent backed by the bridge's default runtime.
///
/// This hides the generic `Runtime` parameter so consumers can write `Agent`
/// with whichever runtime is default.
pub type Agent = agent::AgentHandle<DefaultRuntime>;

/// Primary entry point for the Antigravity bridge.
///
/// Wraps the runtime and provides a clean Rust API for creating agents.
pub struct AgyBridge<R: agent::Runtime + 'static = DefaultRuntime> {
    runtime: Arc<R>,
}

impl<R: agent::Runtime + 'static> Clone for AgyBridge<R> {
    fn clone(&self) -> Self {
        Self {
            runtime: Arc::clone(&self.runtime),
        }
    }
}

/// Builder for constructing an [`AgyBridge`] instance.
///
/// Created via [`AgyBridge::builder()`]. All settings have sensible defaults;
/// call [`.build()`](Self::build) to finalise.
pub struct AgyBridgeBuilder {
    config: runtime::RuntimeConfig,
}

impl AgyBridgeBuilder {
    /// Set the mpsc channel buffer size for the command channel.
    ///
    /// Python backend only — the native backend has no command channel.
    #[must_use]
    pub fn channel_capacity(mut self, capacity: usize) -> Self {
        self.config.channel_capacity = capacity;
        self
    }

    /// Set the timeout for joining the Python thread on shutdown.
    ///
    /// Python backend only.
    #[must_use]
    pub fn shutdown_timeout(mut self, timeout: std::time::Duration) -> Self {
        self.config.shutdown_timeout = timeout;
        self
    }

    /// Set the delay between successive chat commands to prevent burst requests.
    ///
    /// Python backend only.
    #[must_use]
    pub fn inter_agent_delay(mut self, delay: std::time::Duration) -> Self {
        self.config.inter_agent_delay = delay;
        self
    }

    /// Set the backend runtime log verbosity.
    ///
    /// Defaults to [`BackendLogLevel::Warn`]. Set to [`BackendLogLevel::Info`]
    /// or [`BackendLogLevel::Debug`] for verbose protocol-level diagnostics.
    ///
    /// Python backend only.
    #[must_use]
    pub fn backend_log_level(mut self, level: runtime::BackendLogLevel) -> Self {
        self.config.backend_log_level = level;
        self
    }

    /// Replace the entire runtime configuration at once.
    ///
    /// Useful when you already have a [`RuntimeConfig`] struct. Individual
    /// setters called *after* this will override the corresponding fields.
    #[must_use]
    pub fn runtime_config(mut self, config: runtime::RuntimeConfig) -> Self {
        self.config = config;
        self
    }

    /// Set the maximum number of consecutive model-quality errors before
    /// aborting a stream. Set to `0` to disable entirely (pure SDK pass-through).
    ///
    /// Defaults to `3` — enough to catch deterministically-bad model output
    /// without cutting off transient hiccups.
    ///
    /// Python backend only.
    #[must_use]
    pub fn max_consecutive_model_errors(mut self, limit: u32) -> Self {
        self.config.max_consecutive_model_errors = Some(limit);
        self
    }

    /// Set the maximum number of consecutive thinking-only/empty steps before
    /// aborting a stream. Set to `0` to disable entirely (pure SDK pass-through).
    ///
    /// Defaults to `500` — a generous ceiling to avoid false positives on
    /// legitimate long chains of thought.
    ///
    /// Python backend only.
    #[must_use]
    pub fn max_consecutive_empty_steps(mut self, limit: u32) -> Self {
        self.config.max_consecutive_empty_steps = Some(limit);
        self
    }

    /// Set the per-channel buffer size for streaming response channels.
    ///
    /// Each chat call creates ~7 channels of this size. Defaults to `256` —
    /// large enough to avoid backpressure under normal workloads.
    ///
    /// Python backend only.
    #[must_use]
    pub fn streaming_channel_buffer(mut self, size: usize) -> Self {
        self.config.streaming_channel_buffer = Some(size);
        self
    }

    /// Set an explicit path to the `localharness` binary.
    ///
    /// Native backend only — the Python backend locates the harness through
    /// the SDK.
    #[must_use]
    pub fn harness_path(mut self, path: impl Into<std::path::PathBuf>) -> Self {
        self.config.harness_binary_path = Some(path.into());
        self
    }

    /// Return a reference to the accumulated [`RuntimeConfig`].
    #[must_use]
    pub const fn config(&self) -> &runtime::RuntimeConfig {
        &self.config
    }

    #[cfg(feature = "python")]
    /// Build the [`AgyBridge`] with the Python runtime.
    ///
    /// # Errors
    ///
    /// Returns an error if the Python runtime fails to initialize.
    pub fn build_python(self) -> Result<AgyBridge<runtime::PythonRuntime>, error::Error> {
        Ok(AgyBridge {
            runtime: Arc::new(runtime::PythonRuntime::new(self.config)?),
        })
    }

    #[cfg(feature = "native")]
    /// Build the [`AgyBridge`] with the native local harness runtime.
    ///
    /// The native backend only consumes
    /// [`harness_path`](Self::harness_path); every other builder setting
    /// configures the Python command loop and is ignored here. Setting one
    /// of those to a non-default value logs a warning rather than failing,
    /// so the same builder chain still works against both backends.
    ///
    /// # Errors
    ///
    /// Returns an error if runtime initialization fails.
    pub fn build_native(self) -> Result<AgyBridge<runtime::NativeRuntime>, error::Error> {
        self.config.validate()?;
        warn_ignored_by_native(&self.config);
        Ok(AgyBridge {
            runtime: Arc::new(runtime::NativeRuntime::new(self.config)),
        })
    }

    /// Build the [`AgyBridge`], starting the default runtime.
    ///
    /// # Errors
    ///
    /// Returns an error if the underlying runtime fails to initialize.
    pub fn build(self) -> Result<AgyBridge<DefaultRuntime>, error::Error> {
        self.config.validate()?;
        #[cfg(feature = "native")]
        {
            self.build_native()
        }
        #[cfg(all(not(feature = "native"), feature = "python"))]
        {
            self.build_python()
        }
        #[cfg(not(any(feature = "native", feature = "python")))]
        {
            tracing::debug!(
                config = ?self.config,
                "Building AgyBridge with UnconfiguredRuntime (no default backend feature enabled)"
            );
            Ok(AgyBridge::with_runtime(runtime::UnconfiguredRuntime))
        }
    }
}

/// Warn about builder settings that the native backend cannot honour.
///
/// These knobs configure the Python command loop and its streaming
/// plumbing; the native backend has neither. Accepting them silently made
/// `AgyBridge::builder().inter_agent_delay(..).build()` a no-op on the
/// default backend, which is indistinguishable from it working.
#[cfg(feature = "native")]
fn warn_ignored_by_native(config: &runtime::RuntimeConfig) {
    let defaults = runtime::RuntimeConfig::default();
    let mut ignored: Vec<&'static str> = Vec::new();
    if config.channel_capacity != defaults.channel_capacity {
        ignored.push("channel_capacity");
    }
    if config.shutdown_timeout != defaults.shutdown_timeout {
        ignored.push("shutdown_timeout");
    }
    if config.inter_agent_delay != defaults.inter_agent_delay && !config.inter_agent_delay.is_zero()
    {
        ignored.push("inter_agent_delay");
    }
    if config.backend_log_level != defaults.backend_log_level {
        ignored.push("backend_log_level");
    }
    if config.max_consecutive_model_errors.is_some() {
        ignored.push("max_consecutive_model_errors");
    }
    if config.max_consecutive_empty_steps.is_some() {
        ignored.push("max_consecutive_empty_steps");
    }
    if config.streaming_channel_buffer.is_some() {
        ignored.push("streaming_channel_buffer");
    }
    if !ignored.is_empty() {
        tracing::warn!(
            settings = ?ignored,
            "These builder settings only apply to the Python backend and are \
             ignored by the native backend"
        );
    }
}

impl<R: agent::Runtime + 'static> AgyBridge<R> {
    /// Create a new bridge instance from an existing runtime Arc.
    #[must_use]
    pub fn new(runtime: Arc<R>) -> Self {
        Self { runtime }
    }

    /// Create a new bridge instance backed by a custom [`Runtime`](agent::Runtime).
    #[must_use]
    pub fn with_runtime(runtime: R) -> Self {
        Self {
            runtime: Arc::new(runtime),
        }
    }

    /// Begin building a new agent on this bridge.
    #[must_use]
    pub fn agent(&self, config: config::AgentConfig) -> AgentBuilder<'_, R> {
        AgentBuilder {
            bridge: self,
            config,
            registry: None,
            hooks: None,
            policy_handler: None,
        }
    }

    /// Convenience shorthand for `self.agent(AgentConfig::default())`.
    #[must_use]
    pub fn default_agent(&self) -> AgentBuilder<'_, R> {
        self.agent(config::AgentConfig::default())
    }

    /// Return a reference to the underlying runtime Arc.
    #[must_use]
    pub fn runtime(&self) -> &Arc<R> {
        &self.runtime
    }
}

#[cfg(feature = "python")]
impl AgyBridge<runtime::PythonRuntime> {
    /// Create a new builder for configuring and constructing a Python [`AgyBridge`].
    #[must_use]
    pub fn python_builder() -> AgyBridgeBuilder {
        AgyBridgeBuilder {
            config: runtime::RuntimeConfig::default(),
        }
    }

    /// Return the number of agents currently live on this bridge.
    ///
    /// # Errors
    ///
    /// Returns an error if querying the active agent count fails.
    pub async fn active_agent_count(&self) -> Result<usize, error::Error> {
        self.runtime.active_agent_count().await
    }
}

impl AgyBridge<DefaultRuntime> {
    /// Create a new builder for configuring and constructing an [`AgyBridge`].
    #[must_use]
    pub fn builder() -> AgyBridgeBuilder {
        AgyBridgeBuilder {
            config: runtime::RuntimeConfig::default(),
        }
    }
}

#[cfg(feature = "native")]
impl AgyBridge<runtime::NativeRuntime> {
    /// Create a new builder for configuring and constructing a native [`AgyBridge`].
    #[must_use]
    pub fn native_builder() -> AgyBridgeBuilder {
        AgyBridgeBuilder {
            config: runtime::RuntimeConfig::default(),
        }
    }

    /// Return the number of agents currently live on this native bridge.
    ///
    /// # Errors
    ///
    /// Returns an error if querying the active agent count fails.
    pub async fn active_agent_count(&self) -> Result<usize, error::Error> {
        self.runtime.active_agent_count().await
    }
}

impl AgyBridge<runtime::UnconfiguredRuntime> {
    /// Query the active agent count on an unconfigured bridge.
    ///
    /// # Errors
    ///
    /// Always returns [`Error::RuntimeNotStarted`].
    pub async fn active_agent_count(&self) -> Result<usize, error::Error> {
        self.runtime.active_agent_count().await
    }
}

/// Builder for creating an [`Agent`] on an [`AgyBridge`].
pub struct AgentBuilder<'a, R: agent::Runtime + 'static = DefaultRuntime> {
    bridge: &'a AgyBridge<R>,
    config: config::AgentConfig,
    registry: Option<tools::ToolRegistry>,
    hooks: Option<hooks::Hooks>,
    policy_handler: Option<Arc<dyn policies::AskUserHandler>>,
}

impl<R: agent::Runtime + 'static> AgentBuilder<'_, R> {
    /// Attach a [`ToolRegistry`] containing custom
    /// Rust tools for the agent.
    #[must_use]
    pub fn tools(mut self, registry: tools::ToolRegistry) -> Self {
        self.registry = Some(registry);
        self
    }

    /// Attach [`Hooks`] for lifecycle event callbacks.
    #[must_use]
    pub fn hooks(mut self, hooks: hooks::Hooks) -> Self {
        self.hooks = Some(hooks);
        self
    }

    /// Attach a custom [`AskUserHandler`] to manage interactive tool-call confirmations.
    #[must_use]
    pub fn policy_handler(mut self, handler: impl policies::AskUserHandler + 'static) -> Self {
        self.policy_handler = Some(Arc::new(handler));
        self
    }

    /// Resume an existing conversation by its SDK id.
    #[must_use]
    pub fn conversation_id(mut self, id: impl Into<String>) -> Self {
        self.config.conversation_id = Some(id.into());
        self
    }

    /// Set the model backend (e.g. `"gemini-3.5-flash"`).
    #[must_use]
    pub fn model(mut self, model: impl Into<String>) -> Self {
        self.config.model = model.into();
        self
    }

    /// Set the API key for backend requests.
    #[must_use]
    pub fn api_key(mut self, key: impl Into<String>) -> Self {
        self.config.api_key = Some(key.into());
        self
    }

    /// Replace the system instructions for the agent.
    #[must_use]
    pub fn system_instructions(
        mut self,
        instructions: impl Into<config::SystemInstructions>,
    ) -> Self {
        self.config.system_instructions = Some(instructions.into());
        self
    }

    /// Set the capabilities configuration for the agent.
    #[must_use]
    pub fn capabilities(mut self, capabilities: config::CapabilitiesConfig) -> Self {
        self.config.capabilities = Some(capabilities);
        self
    }

    /// Append workspace directories to the agent's permitted filesystem scope.
    #[must_use]
    pub fn workspaces(
        mut self,
        workspaces: impl IntoIterator<Item = impl Into<std::path::PathBuf>>,
    ) -> Self {
        self.config
            .workspaces
            .extend(workspaces.into_iter().map(Into::into));
        self
    }

    /// Replace the policy rules governing tool-call execution.
    ///
    /// Use [`extend_policies`](Self::extend_policies) if you want to append rules
    /// on top of the existing `AgentConfig::policies` list.
    #[must_use]
    pub fn policies(
        mut self,
        policies: impl IntoIterator<Item = impl Into<policies::PolicyRule>>,
    ) -> Self {
        self.config.policies = policies.into_iter().map(Into::into).collect();
        self
    }

    /// Append additional policy rules to the agent's existing policy list.
    #[must_use]
    pub fn extend_policies(
        mut self,
        policies: impl IntoIterator<Item = impl Into<policies::PolicyRule>>,
    ) -> Self {
        self.config
            .policies
            .extend(policies.into_iter().map(Into::into));
        self
    }

    /// Append triggers that autonomously wake the agent.
    #[must_use]
    pub fn triggers(
        mut self,
        triggers: impl IntoIterator<Item = impl Into<triggers::TriggerEntry>>,
    ) -> Self {
        self.config
            .triggers
            .extend(triggers.into_iter().map(Into::into));
        self
    }

    /// Append MCP servers for the agent.
    #[must_use]
    pub fn mcp_servers(
        mut self,
        servers: impl IntoIterator<Item = impl Into<config::McpServer>>,
    ) -> Self {
        self.config
            .mcp_servers
            .extend(servers.into_iter().map(Into::into));
        self
    }

    /// Append paths for agent skills.
    #[must_use]
    pub fn skills(
        mut self,
        skills: impl IntoIterator<Item = impl Into<std::path::PathBuf>>,
    ) -> Self {
        self.config
            .skills
            .extend(skills.into_iter().map(Into::into));
        self
    }

    /// Append inline skills defined directly in memory.
    #[must_use]
    pub fn inline_skills(
        mut self,
        inline_skills: impl IntoIterator<Item = impl Into<config::InlineSkill>>,
    ) -> Self {
        self.config
            .inline_skills
            .extend(inline_skills.into_iter().map(Into::into));
        self
    }

    /// Configure custom tool names that immediately finish the active turn once
    /// they execute and return `Ok(ToolOutput)`.
    ///
    /// Every name must be registered via [`tools`](Self::tools); unknown names
    /// fail agent creation. Prefer the typed [`finish_on`](Self::finish_on).
    #[must_use]
    pub fn finish_on_tools(mut self, tools: impl IntoIterator<Item = impl Into<String>>) -> Self {
        self.config
            .finish_on_tools
            .extend(tools.into_iter().map(Into::into));
        self
    }

    /// Typed variant of [`finish_on_tools`](Self::finish_on_tools): finish the turn
    /// as soon as tool `T` succeeds. The name comes from `T::NAME`, so it cannot
    /// drift from the registered tool.
    #[must_use]
    pub fn finish_on<T: tools::RustTool>(self) -> Self {
        self.finish_on_tools([T::NAME])
    }

    /// Set the minimum sanitization applied to every custom tool output
    /// (see [`config::AgentConfig::tool_output_floor`]).
    #[must_use]
    pub const fn tool_output_floor(mut self, floor: tools::OutputSanitization) -> Self {
        self.config.tool_output_floor = floor;
        self
    }

    /// Insert a single per-agent environment variable forwarded to `localharness`.
    #[must_use]
    pub fn env(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
        self.config.env.insert(key.into(), value.into());
        self
    }

    /// Insert multiple per-agent environment variables forwarded to `localharness`.
    #[must_use]
    pub fn envs<K: Into<String>, V: Into<String>>(
        mut self,
        vars: impl IntoIterator<Item = (K, V)>,
    ) -> Self {
        for (k, v) in vars {
            self.config.env.insert(k.into(), v.into());
        }
        self
    }

    /// Disable or enable the `define_subagent` builtin tool on this agent.
    #[must_use]
    pub fn disable_define_subagent_tool(mut self, disable: bool) -> Self {
        let caps = self
            .config
            .capabilities
            .get_or_insert_with(config::CapabilitiesConfig::default);
        caps.disable_define_subagent_tool = disable;
        self
    }

    /// Disable or enable the `manage_subagents` builtin tool on this agent (`0.1.24`+).
    #[must_use]
    pub fn disable_manage_subagents_tool(mut self, disable: bool) -> Self {
        let caps = self
            .config
            .capabilities
            .get_or_insert_with(config::CapabilitiesConfig::default);
        caps.disable_manage_subagents_tool = disable;
        self
    }

    /// Configure the Gemini Developer API backend (`GeminiConfig`).
    #[must_use]
    pub fn gemini(mut self, gemini: config::GeminiConfig) -> Self {
        self.config.gemini = Some(gemini);
        self
    }

    /// Configure the Google Cloud Vertex AI backend (`VertexConfig`, `0.1.24`+).
    #[must_use]
    pub fn vertex(mut self, vertex: config::VertexConfig) -> Self {
        self.config.vertex = Some(vertex);
        self
    }

    /// Configure an external OpenAI-compatible server backend (`LocalOpenAIConfig`, `0.1.24`+).
    #[must_use]
    pub fn local_openai(mut self, local_openai: config::LocalOpenAIConfig) -> Self {
        self.config.local_openai = Some(local_openai);
        self
    }

    /// Configure a local LiteRT-LM model backend (`LiteRTConfig`, `0.1.24`+; Python runtime only).
    #[must_use]
    pub fn litert(mut self, litert: config::LiteRTConfig) -> Self {
        self.config.litert = Some(litert);
        self
    }

    /// Validate configuration and create the agent.
    ///
    /// # Errors
    ///
    /// Returns [`Error::InvalidConfig`] if configuration
    /// validation fails, or a backend error if agent creation fails.
    pub async fn build(mut self) -> Result<agent::AgentHandle<R>, error::Error> {
        // Validate capabilities.
        if let Some(ref caps) = self.config.capabilities {
            caps.validate().map_err(|msg| error::Error::InvalidConfig {
                message: msg.to_string(),
            })?;
        }

        // Validate response_schema.
        if let Some(ref schema) = self.config.response_schema {
            schema
                .validate()
                .map_err(|msg| error::Error::InvalidConfig {
                    message: msg.to_string(),
                })?;
        }

        // Handle tool registry.
        let arc_registry = if let Some(registry) = self.registry {
            if !self.config.tools.is_empty() {
                return Err(error::Error::InvalidConfig {
                    message: "config.tools is non-empty and a ToolRegistry was also provided; \
                              pass tools via the registry or via config.tools, not both"
                        .to_string(),
                });
            }
            self.config.tools = registry.definitions();
            Some(agent::floored_registry(
                registry,
                self.config.tool_output_floor,
            ))
        } else {
            None
        };

        // Handle hooks.
        let arc_hooks = if let Some(hooks) = self.hooks {
            if !self.config.hooks.is_empty() {
                return Err(error::Error::InvalidConfig {
                    message: "config.hooks is non-empty and a Hooks instance was also provided; \
                              configure hooks via Hooks or config.hooks, not both"
                        .to_string(),
                });
            }
            self.config.hooks = hooks.entries();
            Some(Arc::new(hooks))
        } else {
            None
        };

        // Handle policy handler.
        let arc_policy = self.policy_handler;

        agent::AgentHandle::new(
            Arc::clone(&self.bridge.runtime),
            self.config,
            arc_registry,
            arc_hooks,
            arc_policy,
        )
        .await
    }
}

impl<'a, R: agent::Runtime + 'static> std::future::IntoFuture for AgentBuilder<'a, R> {
    type Output = Result<agent::AgentHandle<R>, error::Error>;
    type IntoFuture =
        std::pin::Pin<Box<dyn std::future::Future<Output = Self::Output> + Send + 'a>>;

    fn into_future(self) -> Self::IntoFuture {
        Box::pin(self.build())
    }
}

